// Matching rules transcribed from `HardcodedChannels.matches` in the Dart source.
export class HardcodedChannels {
  static readonly all: HardcodedChannel[] = HARDCODED_CHANNELS;

  static matches(streamName: string, keywords: readonly string[], exclude?: readonly string[]): boolean {
    const lower = String(streamName || '').toLowerCase();
    if (exclude && exclude.length) {
      for (const ex of exclude) {
        if (lower.includes(ex.toLowerCase())) return false;
      }
    }
    for (const kw of keywords) {
      const kwLower = kw.toLowerCase().trim();
      if (!kwLower) continue;
      if (kwLower.length <= 3) {
        const escaped = kwLower.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        if (new RegExp(`(?:^|[^a-zA-Z0-9])${escaped}(?:$|[^a-zA-Z0-9])`).test(lower)) return true;
      } else if (lower.includes(kwLower)) {
        return true;
      }
    }
    return false;
  }

  static byId(id: string): HardcodedChannel | undefined {
    return HARDCODED_CHANNELS.find((channel) => channel.id === id);
  }

  static byCategory(category: string): HardcodedChannel[] {
    const target = category.toLowerCase();
    return HARDCODED_CHANNELS.filter((channel) => channel.category.toLowerCase() === target);
  }
}

/** All Live TV channels: built-ins wearing reviewed art, then the extras. */
export const liveChannels: HardcodedChannel[] = HARDCODED_CHANNELS;
